"""Authentic German lesson seed data for Sprechen.

180 lessons across A1, A2, B1, B2, C1, C2 — each a real CEFR-aligned lesson
with dialogue, grammar focus, vocabulary, exercises, and a cultural note.
"""
from __future__ import annotations

from typing import List

from sqlalchemy import select
from sqlalchemy.ext.asyncio import AsyncSession


def _t(role: str, de: str, en: str) -> dict:
    return {"role": role, "german": de, "english": en, "vocabulary": [], "pronunciation_tips": []}

def _v(word: str, translation: str, example: str, phonetic: str | None = None) -> dict:
    return {"word": word, "translation": translation, "phonetic": phonetic, "example_sentence": example}

def _ex_fib(sentence, options, correct=None, hint=None) -> dict:
    # New-style: (desc, sentences_list, answers_list) — correct is a list of strings
    if isinstance(correct, list):
        return {"type": "fill_in_blank", "description": sentence, "sentences": options, "answers": correct}
    # Old-style: (sentence_with_blank, options_list, correct_index_int, hint_str)
    return {"type": "fill_in_blank", "sentence_with_blank": sentence, "options": options, "correct_index": correct, "hint": hint}

def _ex_mc(question, options, correct=None, explanation=None) -> dict:
    # New-style: (desc, list_of_(question, options, correct) tuples)
    if correct is None and isinstance(options, list) and options and isinstance(options[0], tuple):
        return {"type": "multiple_choice", "description": question,
                "questions": [{"question": q, "options": o, "correct_index": c} for q, o, c in options]}
    # Old-style: (question, options_list, correct_index, explanation)
    return {"type": "multiple_choice", "question": question, "options": options, "correct_index": correct, "explanation": explanation}

def _ex_arr(scrambled, correct_sentence, hint=None) -> dict:
    # New-style: (desc, list_of_(words_list, correct_str) tuples)
    if isinstance(correct_sentence, list) and correct_sentence and isinstance(correct_sentence[0], tuple):
        return {"type": "arrange_words", "description": scrambled,
                "exercises": [{"scrambled_words": s, "correct_sentence": c} for s, c in correct_sentence]}
    # Old-style: (scrambled_list, correct_sentence_str, hint)
    return {"type": "arrange_words", "scrambled_words": scrambled, "correct_sentence": correct_sentence, "hint": hint}

def _ex_tr(source, model, src_lang: str = "en", tgt_lang: str = "de") -> dict:
    # New-style: (desc, list_of_(source, target) tuples)
    if isinstance(model, list) and model and isinstance(model[0], tuple):
        return {"type": "translate", "description": source,
                "pairs": [{"source": s, "model_answer": m} for s, m in model]}
    # Old-style: (source_text, model_answer, src_lang, tgt_lang)
    return {"type": "translate", "source_text": source, "source_lang": src_lang, "target_lang": tgt_lang, "model_answer": model}

def _ex_sp(prompt, topic, min_words: int = 25) -> dict:
    # New-style: (desc, prompts_list)
    if isinstance(topic, list):
        return {"type": "speaking_prompt", "description": prompt, "prompts": topic}
    # Old-style: (prompt_text, expected_topic, min_words)
    return {"type": "speaking_prompt", "prompt_text": prompt, "expected_topic": topic, "min_words": min_words}

def _gex(de: str, en: str, breakdown=None, table=None, examples=None) -> dict:
    # New-style grammar focus: (rule, explanation, example, table_list, examples_list)
    if table is not None or examples is not None:
        return {"rule_name": de, "explanation": en, "formula": breakdown or "",
                "table": table or [], "examples": examples or []}
    # Old-style inline example: (german, english, breakdown)
    return {"german": de, "english": en, "breakdown": breakdown}


# =====================================================================
# A1 — Lessons 1–30
# =====================================================================

