        _ex_arr(["Ich", "hätte", "gern", "die", "Suppe"], "Ich hätte gern die Suppe.", "Use 'hätte gern' for polite ordering."),
        _ex_tr("The bill, please.", "Die Rechnung, bitte."),
        _ex_sp("Beschreibe dein Lieblingsrestaurant und was du dort bestellst.", "restaurant ordering", 30),
