        _ex_mc("'Es ___ morgen regnen.' Which form of werden?",["werde","wirst","wird","werden"],2,"3rd person singular: wird."),
        _ex_arr(["Wir","haben","vor","mit","dem","Zug","zu","fahren"],"Wir haben vor, mit dem Zug zu fahren.","vorhaben + zu + Infinitiv."),
        _ex_tr("I am looking forward to the holiday. I will travel to Spain.","Ich freue mich auf den Urlaub. Ich werde nach Spanien reisen."),
