        _ex_mc("'Gibt es hier ___ Apotheke?' Which article?",["ein","einen","eine","einem"],2,"Apotheke is feminine: eine (acc. f.)."),
        _ex_arr(["Es","gibt","viele","Museen","in","dieser","Stadt"],"Es gibt viele Museen in dieser Stadt.","es gibt always followed by accusative object."),
