        _v("die Hauptstadt","capital city","Berlin ist die Hauptstadt."),
        _v("im Norden / Süden","in the north / south","Hamburg liegt im Norden."),
        _v("der Berg","mountain","Der Zugspitze ist hoch."),
        _v("der See / das Meer","lake / sea","Der Bodensee ist groß."),
