        _ex_mc("Which river flows through western Germany?",["Donau","Elbe","Rhein","Weser"],2,"Der Rhein flows through western Germany."),
        _ex_arr(["Hamburg","liegt","im","Norden","an","der","Nordsee"],"Hamburg liegt im Norden an der Nordsee.","Location with im + direction and an + Dativ."),
