        _ex_mc("'Das Projekt, ___ viele vertrauen, ist erfolgreich.' Correct relative pronoun?",["das","dem","den","dessen"],1,"vertrauen + Dativ n.: dem."),
        _ex_arr(["Obwohl","das","Ziel","erreicht","worden","ist","wird","weiter","gearbeitet"],"Obwohl das Ziel erreicht worden ist, wird weiter gearbeitet.","Passiv Perfekt in obwohl-clause."),
        _ex_tr("Although the goal has been achieved, the project, which many people trust, will continue without interruption.","Obwohl das Ziel erreicht worden ist, wird das Projekt, dem viele vertrauen, ohne Unterbrechung weitergehen."),
        _ex_sp("Reflect on your B1 German journey. What was hard? What helped most? What are your concrete goals for B2? Speak for at least 3 minutes.","B1 reflection and B2 goals",180),
