async def seed_default_lessons(session: AsyncSession) -> int:
    """Insert or update all lessons. Returns count of upserted rows."""
    from models.orm_models import Lesson  # avoid circular at module level

    count = 0
    for lesson_data in LESSONS:
        title = lesson_data.get("title", "")
        existing = (await session.execute(
            select(Lesson).where(Lesson.title == title)
        )).scalars().first()

        if existing:
            existing.level = lesson_data.get("level", existing.level)
            existing.scenario = lesson_data.get("scenario", existing.scenario)
            existing.topic = lesson_data.get("topic", existing.topic or "")
            existing.content_json = lesson_data
        else:
            session.add(Lesson(
                title=title,
                level=lesson_data.get("level", "A1"),
                scenario=lesson_data.get("scenario", "free"),
                topic=lesson_data.get("topic", ""),
                order_index=count,
                content_json=lesson_data,
            ))
        count += 1

    return count
